package server

func init() { pages["managed_cp"] = managedCPTemplate }

const nodeAddressTemplate = `{{define "node_address"}}{{if eq .Kind "CP"}}{{if .ManagedMAC}}<code>{{.ManagedMAC}}</code><br><small>ADPTADR <code>{{.ADPTADR}}</code></small>{{else}}No managed MAC{{end}}{{else}}{{if .HostingCPName}}Hosted by <code>{{.HostingCPNetID}}.{{.HostingCPName}}</code>{{else}}Hosting CP unknown{{end}}{{end}}{{end}}`

const managedCPTemplate = `{{define "content"}}
<h1>{{if .All}}All managed CP addresses{{else}}My managed LLC MACs{{end}}</h1>
<p>Assign a virtual MAC only to a configured CP that an LLC-facing router needs to reach. LUs use their hosting CP's address. The local <code>02:53:4E</code> prefix validates an address; it does not authenticate a router. You must enter the ADPTADR value in OS/400 yourself.</p>
{{if not .All}}{{if .User.NetID}}<form method="post" action="/llc-macs" class="row g-2 mb-4"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="col-auto"><span class="input-group-text"><code>{{.User.NetID}}</code>.</span></div><div class="col-auto"><input class="form-control" name="cp_name" placeholder="CP name" maxlength="8" pattern="[A-Za-z@#$][A-Za-z0-9@#$]{0,7}" required></div><div class="col-auto"><button class="btn btn-primary">Assign virtual MAC to CP</button></div></form>{{else}}<div class="alert alert-warning">Set your NETID in your profile before assigning managed CP addresses.</div>{{end}}{{end}}
<div class="table-responsive"><table class="table table-striped"><thead><tr><th>Control point</th>{{if .All}}<th>Owner</th>{{end}}<th>Virtual MAC</th><th>OS/400 ADPTADR</th><th>State</th><th>Advertising routers</th><th>Manage</th></tr></thead><tbody>
{{range .Items}}<tr><td><code>{{.NetID}}.{{.CPName}}</code></td>{{if $.All}}<td><a href="/profiles/{{.OwnerID}}">View owner</a></td>{{end}}<td><code>{{.MACColon}}</code></td><td><code>{{.ADPTADR}}</code></td><td>{{if .RetiredAt}}Retired{{else if not .Enabled}}Disabled{{else if .Online}}Online{{else}}Offline{{end}}</td><td>{{range .Advertisers}}{{.}}<br>{{else}}—{{end}}</td><td>{{if not .RetiredAt}}<form method="post" action="/llc-macs/{{.ID}}/enabled" class="d-inline"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="enabled" value="{{if .Enabled}}0{{else}}1{{end}}"><button class="btn btn-outline-primary btn-sm">{{if .Enabled}}Disable{{else}}Enable{{end}}</button></form> <form method="post" action="/llc-macs/{{.ID}}/retire" class="d-inline"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="btn btn-outline-danger btn-sm">Retire</button></form>{{end}}</td></tr>{{else}}<tr><td colspan="{{if .All}}7{{else}}6{{end}}">No managed CP addresses.</td></tr>{{end}}
</tbody></table></div><p class="text-muted">Retired addresses remain reserved and are never automatically reused. Route withdrawal and disconnect leave the address book unchanged.</p>{{end}}`
